    for i, tabela in enumerate(tabelas, start=1):
        tabela["id"] = f"tabela_{i:03d}"
        tabela["secao"] = encontrar_secao(tabela["pagina"], mapa)

    doc["tabelas"] = {t["id"]: t for t in tabelas}
    return doc

