def dms_to_dd(dms, ref):
                        deg, min_, sec = [float(x.num) / float(x.den) for x in dms]
                        dd = deg + min_ / 60 + sec / 3600
                        if ref in ["S", "W"]:
                            dd *= -1
                        return dd
